.modal-content{background:rgba(28,28,30,0.75);backdrop-filter:blur(25px);-webkit-backdrop-filter:blur(25px);border-radius:1.5rem;border:1px solid rgba(255,255,255,0.12);box-shadow:0 16px 48px rgba(0,0,0,0.3);width:100%;max-width:32rem;padding:2rem;animation:modalFadeIn 0.3s ease forwards}
@keyframes modalFadeIn{from{opacity:0;transform:translateY(20px)}to{opacity:1;transform:translateY(0)}}
.modal-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:1.5rem}
.modal-header h3{font-size:1.5rem;font-weight:700}
.close-btn{background:none;border:none;color:#8e8e93;cursor:pointer;font-size:2rem;line-height:1;padding:0;width:2rem;height:2rem;display:flex;align-items:center;justify-content:center;transition:color 0.2s;outline:none;-webkit-tap-highlight-color:transparent}
.close-btn:hover{color:#fff}
.calendar-nav{display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem}
.calendar-nav button{background:none;border:none;color:#f5f5f7;cursor:pointer;padding:0.5rem;border-radius:9999px;transition:background 0.2s;outline:none;-webkit-tap-highlight-color:transparent}
.calendar-nav button:hover{background:rgba(255,255,255,0.1)}
.calendar-nav button svg{width:1.5rem;height:1.5rem}
.calendar-nav h4{font-size:1.125rem;font-weight:600}
.calendar-grid{display:grid;grid-template-columns:repeat(7,1fr);gap:0.5rem}
.weekday{display:flex;justify-content:center;align-items:center;aspect-ratio:1/1;font-weight:500;font-size:0.8rem;color:rgba(235,235,245,0.6)}
.calendar-day{display:flex;justify-content:center;align-items:center;aspect-ratio:1/1;cursor:pointer;border-radius:9999px;transition:background-color 0.2s,color 0.2s,transform 0.2s;outline:none;-webkit-tap-highlight-color:transparent;touch-action:manipulation}
.calendar-day:not(.disabled):not(.empty):hover{background:rgba(255,255,255,0.1);transform:scale(1.05)}
.calendar-day:not(.disabled):not(.empty):active{transform:scale(0.98)}
.calendar-day.disabled{color:rgba(235,235,245,0.3);cursor:not-allowed}
.calendar-day.selected{background:#0a84ff;color:#fff;font-weight:600;transform:scale(1.1)}
.time-slots-container{margin-top:1.5rem;display:none}
.time-slots-container.active{display:block}
.time-slots-container h4{font-weight:600;margin-bottom:0.75rem;font-size:1.125rem}
.time-slots{display:grid;grid-template-columns:repeat(3,1fr);gap:0.75rem}
.time-slot{cursor:pointer;transition:background-color 0.2s,border-color 0.2s,color 0.2s;border:1px solid rgba(255,255,255,0.2);text-align:center;padding:0.5rem;border-radius:0.5rem;outline:none;-webkit-tap-highlight-color:transparent;touch-action:manipulation}
.time-slot:hover{background:rgba(255,255,255,0.1)}
.time-slot:active{transform:scale(0.98)}
.time-slot.selected{background:#0a84ff;border-color:#0a84ff;color:#fff}
.confirm-btn{width:100%;margin-top:2rem;transition:opacity 0.2s}
.confirm-btn:disabled{opacity:0.5;cursor:not-allowed}
.payment-info{background:rgba(255,255,255,0.05);border-radius:1rem;padding:1.5rem;margin-top:1.5rem}
.payment-info h4{font-size:1.125rem;font-weight:600;margin-bottom:1rem;color:#0a84ff}
.info-row{display:flex;justify-content:space-between;align-items:center;padding:0.5rem 0;border-bottom:1px solid rgba(255,255,255,0.1)}
.info-row:last-child{border-bottom:none}
.info-label{color:#8e8e93;font-size:0.875rem}
.info-value{color:#f5f5f7;font-weight:500;text-align:right;word-break:break-all;max-width:60%}
.copy-btn{background:rgba(10,132,255,0.15);color:#0a84ff;border:1px solid rgba(10,132,255,0.3);padding:0.375rem 0.75rem;border-radius:0.5rem;font-size:0.875rem;cursor:pointer;transition:all 0.2s;margin-left:0.5rem}
.copy-btn:hover{background:rgba(10,132,255,0.25)}
.copy-btn:active{transform:scale(0.95)}
@media(min-width:640px){h1{font-size:4.5rem}.time-slots{grid-template-columns:repeat(4,1fr)}}
</style>
